	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:legacy-file-lifecycle:p> ?o . FILTER(?o = 1) }", null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter value) {
				if (found[0] == null) {
					found[0] = value;
				}
				super.meet(value);
			}
		});
		assertNotNull(found[0]);
		return found[0];
	}

	private static void writeAndCheck(Path directory, Path legacy, boolean enabled, int subject, int rows)
			throws Exception {
		try (AutoCloseable preserve = () -> assertLegacy(legacy)) {
			LmdbStore store = new LmdbStore(directory.toFile(), config(enabled));
			try (AutoCloseable shutdown = store::shutDown) {
				store.init();
				assertLegacy(legacy);
				LmdbTestUtil.awaitPostReadyInitialization(store, 20, TimeUnit.SECONDS);
				try (NotifyingSailConnection connection = store.getConnection()) {
					connection.begin(IsolationLevels.READ_COMMITTED);
					connection.addStatement(VF.createIRI("urn:legacy-file-lifecycle:s" + subject), P, O);
					connection.commit();
					assertTrue(connection.hasStatement(VF.createIRI("urn:legacy-file-lifecycle:s" + subject), P, O,
							false));
				}
				assertLegacy(legacy);
				if (enabled) {
					assertRows(store, rows);
					store.getBackingStore().getSketchBasedJoinEstimator().persistIfDirty();
				}
			}
		}
		assertLegacy(legacy);
	}

	private static void assertRows(LmdbStore store, int rows) throws Exception {
		assertTrue(store.awaitSketchesReady(20, TimeUnit.SECONDS), "the synopsis must be current after readiness");
		SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
		QuadEvidence evidence = estimator.synopsisService()
				.probe(new QuadProbe(QuadProbe.PREDICATE,
						QuadProbe.SUBJECT, 0L, QuadValueHash.hash(P), 0L, 0L, estimator.quadSnapshotIdentity()));
		assertTrue(evidence.usable(), "the query must not use unavailable or stale evidence");
		assertEquals((double) rows, evidence.rows().estimate(), 0.0d);
	}

	private static void assertLegacy(Path legacy) throws Exception {
		assertTrue(Files.isRegularFile(legacy));
		LmdbLegacyV4TestFixture.assertUnchanged(legacy.getParent());
	}

	private static LmdbStoreConfig config(boolean enabled) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(enabled)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
